      "text": "After all, they normally pretended she didn’t have a sister. ‘No,’ she said sharply. ‘Why?’ ‘Funny stuff on the news,’ Mr Dursley mumbled. ‘Owls ... shooting stars ... and there were a lot of funny-looking people in town today ...’ ‘So?’ snapped Mrs Dursley. ‘Well, I just thought ... maybe ... it was something to do with ... you know ... her lot.’ Mrs Dursley sipped her tea through pursed lips.",
