      "text": "I must have passed a dozen feasts and parties on my way here.’ Professor McGonagall sniffed angrily. ‘Oh yes, everyone’s celebrating, all right,’ she said impatiently. ‘You’d think they’d be a bit more careful, but no – even the Muggles have noticed something’s going on.",
