      "text": "It’s just astounding ... of all the things to stop him ... but how in the name of heaven did Harry survive?’ ‘We can only guess,’ said Dumbledore. ‘We may never know.’ Professor McGonagall pulled out a lace handkerchief and dabbed at her eyes beneath her spectacles.",
