      "text": "I suppose it was he who told you I’d be here, by the way?’ ‘Yes,’ said Professor McGonagall. ‘And I don’t suppose you’re going to tell me why you’re here, of all places?’ ‘I’ve come to bring Harry to his aunt and uncle.",
