      "text": "Then, suddenly, Hagrid let out a howl like a wounded dog. ‘Shhh!’ hissed Professor McGonagall. ‘You’ll wake the Muggles!’ ‘S-s-sorry,’ sobbed Hagrid, taking out a large spotted handkerchief and burying his face in it. ‘But I c-c-can’t stand it – Lily an’ James dead – an’ poor little Harry off ter live with Muggles –’ ‘Yes, yes, it’s all very sad, but get a grip on yourself, Hagrid, or we’ll be found,’ Professor McGonagall whispered, patting Hagrid gingerly on the arm as Dumbledore stepped over the low garden wall and walked to the front door.",
